SELECT * FROM (SELECT city, CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN country = 'UK' THEN 1 ELSE 0 END) AS uk_count, ROUND(STDDEV(rating), 2) AS stddev_rating FROM suppliers GROUP BY city, CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END) AS sub WHERE stddev_rating >= 73 ORDER BY stddev_rating DESC
